DELETE FROM `quest_template_locale` WHERE `locale` = 'deDE' AND `ID` IN (14265, 14266, 14269, 14272, 14273, 14274, 14275, 14276, 14277, 14278, 14279, 14280, 14281, 14283, 14285, 14286, 14287, 14288, 14289, 14290, 14291);
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `OfferRewardText`, `RequestItemsText`, `EndText`, `ObjectiveText1`, `VerifiedBuild`) VALUES
(14265, 'deDE', 'Euer Lehrmeister', 'Die meisten von uns haben es lebend hierher geschafft ... aber auf dieser Seite der Stadt gibt es auch Worgen.$B$BSobald alle hier eingetroffen sind, werden wir weiter nach Süden ziehen.$B$BDa fällt mir ein: Jemand hat nach Euch gefragt. Ein Typ namens Cleese meinte, Ihr wärt einer seiner Lehrlinge und wollte sicherstellen, dass es Euch gut geht.', 'Redet mit Unteroffizier Cleese im Militärviertel.', '$N! Wo wart Ihr?$B$BWie auch immer, es ist großartig, Euch in einem Stück wiederzusehen.', '', '', '', 0),
(14266, 'deDE', 'Sturmangriff', 'Ihr seid am Leben, $N! Also habe ich wohl meine Sache richtig gemacht.$B$BEine Schande, dass unser Unterricht so abrupt abgebrochen wurde. Aber vielleicht kann ich Euch noch ein oder zwei Dinge beibringen, die Euch in Zeiten wie diesen von Nutzen sein könnten.$B$BProbiert Eure neuen Kampfkünste an den Blutfangworgen im Westen aus.', 'Sprecht mit Unteroffizier Cleese und erlernt ''Sturmangriff''. Übt anschließend ''Sturmangriff'' gegen einen Blutfangworgen.', 'Gute Arbeit!', 'Ihr seid ein schneller Lerner, $N. Werdet aber nicht gleich übermütig.', '', 'Übt ''Sturmangriff''', 0),
(14269, 'deDE', 'Jemand sucht nach Euch', 'Die meisten von uns haben es lebend hierher geschafft ... aber auf dieser Seite der Stadt gibt es auch Worgen.$B$BSobald alle hier eingetroffen sind, werden wir weiter nach Süden ziehen.$B$BDa fällt mir ein: Jemand hat nach Euch gefragt. Eine Frau namens Loren... Sie schien etwas enttäuscht zu sein, als ich ihr sagte, dass es Euch gut geht.$B$BIch glaube sie sagte, sie schulde Euch Gold.', 'Sprecht mit Loren der Hehlerin im Militärviertel.', 'Oh, da seid Ihr ja!', '', '', '', 0),
(14272, 'deDE', 'Ausweiden', 'Schön, Euch lebend wiederzusehen!$B$BNein, natürlich habe ich das Gold nicht, das ich Euch schulde. Jetzt ist nun wirklich nicht die Zeit, darüber zu diskutieren!$B$BHört zu, vielleicht kann ich Euch ein oder zwei Tricks beibringen, die Euch helfen werden, trotz des ganzen Gemetzels hier Eure Haut zu retten. Dann wären wir sogar mehr als quitt. Was meint Ihr?$B$BWenn Eure Lektion vorbei ist solltet Ihr Eure neuen Kampfkünste an den Blutfangworgen im Westen ausprobieren.', 'Sprecht mit Loren der Hehlerin und lernt ''Ausweiden''. Übt ''Ausweiden'' an einem Blutfangworgen.', 'Übertreibt es jetzt nur nicht. Erinnert Euch einfach daran, wer Euch alles beigebracht hat, was Ihr wisst.$B$BUnd jetzt lasst uns sehen, wie wir mit heiler Haut aus dieser Stadt kommen.', 'Verhaltet Euch still, dann schnappt sich der $r hoffentlich einen anderen armen Wicht anstelle von uns.', '', 'Übt ''Ausweiden''', 0),
(14273, 'deDE', 'Zwielichtige Gesellen', 'Die meisten von uns haben es lebend hierher geschafft ... aber auf dieser Seite der Stadt gibt es auch Worgen.$B$BSobald alle hier eingetroffen sind, werden wir weiter nach Süden ziehen.$B$BDa fällt mir ein: Jemand hat nach Euch gefragt. So ein seltsamer Geselle namens Vitus ... der war echt unheimlich.$B$BEr hat die ganze Zeit von einem "verbotenen Wissen" erzählt, das er sich angeeignet hat.', 'Sprecht mit Vitus Dunkelwandler im Militärviertel.', 'Dunkelheit ist über unser Land gekommen. Und nicht die übliche Art Dunkelheit, wenn Ihr versteht, was ich meine.', '', '', '', 0),
(14274, 'deDE', 'Feuerbrand', 'Also ist es wahr! Ihr seid am Leben!$B$BIch hatte nie die Gelegenheit, meine größte Entdeckung mit Euch zu teilen. Aus dem geheimen Wissen der kaum entzifferbaren Bücher von Balcephoth dem Teufelsschatten... lernte ich die verbotenen Geheimnisse des...$B$BFeuerbrands!$B$BNatürlich werde ich dieses Wissen mit Euch teilen... Wer sonst hier wüsste solch mächtige Geheimnisse zu schätzen?$B$BGeht jetzt und übt Euren neuen Zauberspruch an den Blutfangworgen im Westen.', 'Sprecht mit Vitus Dunkelwandler, um ''Feuerbrand'' zu lernen. Übt ''Feuerbrand'' an einem Blutfangworgen.', 'Ja! Könnt Ihr die Macht spüren?', '', '', 'Übt ''Feuerbrand''', 0),
(14275, 'deDE', 'Jemand ist Euch auf der Fährte', 'Die meisten von uns haben es lebend hierher geschafft ... aber auf dieser Seite der Stadt gibt es auch Worgen.$B$BSobald alle hier eingetroffen sind, werden wir weiter nach Süden ziehen.$B$BDa fällt mir ein: Jemand hat nach Euch gefragt. Ein Mann namens Blake. Sagte etwas über einen Plan, in die Wälder zu flüchten.', 'Sprecht mit Jäger Blake im Militärviertel.', '$N! Ich wusste, dass Ihr hier irgendwo sein müsst.', '', '', '', 0),
(14276, 'deDE', 'Zuverlässiger Schuss', 'Ich habe gute und schlechte Nachrichten.$B$BDie schlechte ist, dass es in den Wäldern mehr Worgen gibt als hier drin... also haben wir keinen sicheren Ort, an den wir uns zurückziehen können.$B$BDie gute Nachricht ist, dass ich Euch noch ein oder zwei Dinge beibringen kann. Wer weiß schon, welche Fähigkeit Euch in Zeiten wie diesen einmal das Leben retten wird?$B$BProbiert Euch doch gegen die Blutfangworgen im Westen aus.', 'Sprecht mit Jäger Blake, um ''Zuverlässiger Schuss'' zu lernen. Übt ''Zuverlässiger Schuss'' zweimal gegen einen Blutfangworgen.', 'Ausgezeichnete Arbeit, $N. Diese $r werden bereuen, dass sie je einen Fuß auf unser Land gesetzt haben.', 'Ihr lernt schnell. Wir werden diesen $r zeigen, wer hier der echte $c ist.', '', 'Übt ''Zuverlässiger Schuss''', 0),
(14277, 'deDE', 'Arkane Anfragen', 'Die meisten von uns haben es lebend hierher geschafft, aber auch in diesem Teil der Stadt gibt es Worgen.$B$BWir werden weiter nach Süden ziehen, sobald sich alle gesammelt haben.$B$BDa fällt mir ein, dass jemand nach Euch gefragt hat. Es war eine Magierin namens Myriam. Sie meinte etwas wie Ihr wärt "bereit".', 'Sprecht mit Myriam Zauberwache im Militärviertel.', 'Ein Schüler der arkanen Künste findet immer einen Weg nach vorne. Ich freue mich, Euch zu sehen, $N.', '', '', '', 0),
(14278, 'deDE', 'Sucht die Schwester', 'Die meisten von uns haben es lebend hierher geschafft ... aber auf dieser Seite der Stadt gibt es auch Worgen.$B$BSobald alle hier eingetroffen sind, werden wir weiter nach Süden ziehen.$B$BDa fällt mir ein: Jemand hat nach Euch gefragt. Eine Geistliche namens Schwester Almyra sagte, Ihr befändet Euch in großer Gefahr und brauchtet den Schutz des Lichts.$B$BIhr solltet mit ihr reden. Sie schien sehr in Sorge zu sein.', 'Sprecht mit Schwester Almyra im Militärviertel.', 'Das Licht ist mit Euch, $N. Ich bin sehr erleichtert, Euch zu sehen.', '', '', '', 0),
(14279, 'deDE', 'Blitzheilung', 'Ihr habt noch viel zu lernen, $N. Und ich habe Euch viel beizubringen.$B$BEs herrschen gefährliche Zeiten, daher fürchte ich, dass wir unsere Lektionen etwas beschleunigen müssen.$B$BHabt keine Angst, $g Bruder:Schwester;. Das Licht wird uns beschützen.', 'Sprecht mit Schwester Almyra, um ''Blitzheilung'' zu lernen. Übt ''Blitzheilung'' an zwei verwundeten Wachen.', 'Ihr seid gesegnet, $N. Das Licht strahlt selbst in diesen finsteren Zeiten auf Euch herab.', '', '', 'Übt ''Blitzheilung''', 0),
(14280, 'deDE', 'Die Winde kennen Euren Namen… anscheinend', 'Die meisten von uns haben es lebend hierher geschafft, aber auch in diesem Teil der Stadt gibt es Worgen.$B$BWir werden weiter nach Süden ziehen, sobald sich alle gesammelt haben.$B$BDa fällt mir ein, dass jemand nach Euch gefragt hat. Es war die Erntehexe Celestine. Sie sagte, die Winde hätten Euren Namen geflüstert.$B$BIhr solltet Euch lieber beeilen, $N. Ihr müsst schnell zurückkommen und den Worgen den Garaus machen, wenn Ihr Euer Gespräch mit der Natur beendet habt.', 'Sprecht mit Celestine Erntedank im Militärviertel.', 'Welcher Segen ereilt uns heute! Ihr seid am Leben und wohlauf!', '', '', '', 0),
(14281, 'deDE', 'Arkane Geschosse', 'Es liegt ein harter Weg vor uns, $N. Wir müssen all unsere geistige Kraft auf unsere Aufgabe richten.$B$BUnd doch reicht dies manchmal nicht aus. Manchmal erfordert eine Lage einfach rohe Feuergewalt.$B$BIch kenne genau den richtigen Zauber und kann ihn Euch gern beibringen. Sobald Ihr ihn erlernt habt, übt ihn an den Blutfangworgen im Westen. Ihr werdet Euren neuen Zauber aber nur einsetzen können, nachdem Ihr einen anderen Zauber gewirkt habt.', 'Sprecht mit Miriam Zauberwache und lernt ''Arkane Geschosse''. Übt ''Arkane Geschosse'' an einem Blutfangworgen.', 'Ihr habt diesen Zauber so schnell und problemlos erlernt. Bald schon werdet Ihr andere unterrichten.', 'Ich wusste gleich, dass Ihr ein begabter Schüler seid!', '', 'Übt ''Arkane Geschosse''', 0),
(14283, 'deDE', 'Verjüngende Berührung', 'Wir standen schon einmal am Rande der Ausrottung, $N. Aber wir Druiden, Hüter des alten Wegs, haben unsere Leute vor der Hungersnot gerettet.$B$BAls wir uns selbst von der Außenwelt abschnitten und unsere Ernte ein Misserfolg war, war es unser Orden, der den Segen der Erde herbeigerufen und die Früchte wieder zum Wachsen gebracht hat.$B$BGenauso wie damals sollten wir unser Schicksal in die Hände einer höheren Macht legen. Kommt mit mir und lernt, was die Wildnis uns zu lehren hat.', 'Sprecht mit Celestine Erntedank, um ''Verjüngung'' zu lernen. Übt ''Verjüngung'' an einer verwundeten Wache.', 'Nicht schlecht. Vielleicht besteht ja doch noch Hoffnung für die alten Wege.', 'Die Erde spricht mit uns, $N. Sie wird uns nicht verlassen. Auch nicht in diesen finsteren Zeiten.', '', 'Übt ''Verjüngung''', 0),
(14285, 'deDE', 'Je mehr, desto sicherer', 'Solange die Worgen es darauf angelegt haben, uns alle Gliedmaßen auszureißen, kann ich Euch leider nicht so viel beibringen, wie ich möchte.$B$BWir sollten wirklich in Betracht ziehen, mit den anderen Überlebenden nach Süden zu ziehen. Wir haben erfahren, dass König Graumähne sich dort aufhält.$B$BWenn wir zusammen bleiben, steigen unsere Überlebenschancen... besonders wenn Ihr neben jemandem steht, der schmackhaft aussieht.', 'Sprecht mit König Genn Graumähne im Militärviertel.', 'Es war klug von Euch, hierher zu kommen. Wenn die Einwohner von Gilneas zusammenhalten, können wir diesen schrecklichen Feind vielleicht doch noch besiegen.', '', '', '', 0),
(14286, 'deDE', 'Je mehr, desto sicherer', 'Ich habe Euch alles beigebracht, was mir derzeit sinnvoll erscheint.$B$BEs ist an der Zeit, dass wir uns den anderen Überlebenden anschließen. Ich habe gehört, dass König Graumähne und seine Königswache sich direkt südlich von hier aufhalten sollen.$B$BWir sollten dorthin gehen und in der Masse Schutz suchen.', 'Sprecht mit König Genn Graumähne im Militärviertel.', 'Es war klug von Euch, hierher zu kommen. Wenn die Einwohner von Gilneas zusammenhalten, können wir diesen schrecklichen Feind vielleicht doch noch besiegen.', '', '', '', 0),
(14287, 'deDE', 'Je mehr, desto sicherer', 'Ich habe Euch alles beigebracht, was mir derzeit sinnvoll erscheint.$B$BEs ist an der Zeit, dass wir uns den anderen Überlebenden anschließen. Ich habe gehört, dass König Graumähne und seine Königswache sich direkt südlich von hier aufhalten sollen.$B$BWir sollten dorthin gehen und in der Masse Schutz suchen.', 'Sprecht mit König Genn Graumähne im Militärviertel.', 'Es war klug von Euch, hierher zu kommen. Wenn die Einwohner von Gilneas zusammenhalten, können wir diesen schrecklichen Feind vielleicht doch noch besiegen.', '', '', '', 0),
(14288, 'deDE', 'Je mehr, desto sicherer', 'Solange die Worgen es darauf angelegt haben, uns alle Gliedmaßen auszureißen, kann ich Euch leider nicht so viel beibringen, wie ich möchte.$B$BWir sollten wirklich in Betracht ziehen, mit den anderen Überlebenden nach Süden zu ziehen. Wir haben erfahren, dass König Graumähne sich dort aufhält.$B$BWenn wir zusammen bleiben, steigen unsere Überlebenschancen... besonders wenn Ihr neben jemandem steht, der schmackhaft aussieht.', 'Sprecht mit König Genn Graumähne im Militärviertel.', 'Es war klug von Euch, hierher zu kommen. Wenn die Einwohner von Gilneas zusammenhalten, können wir diesen schrecklichen Feind vielleicht doch noch besiegen.', '', '', '', 0),
(14289, 'deDE', 'Je mehr, desto sicherer', 'Ich habe Euch alles beigebracht, was mir derzeit sinnvoll erscheint.$B$BEs ist an der Zeit, dass wir uns den anderen Überlebenden anschließen. Ich habe gehört, dass König Graumähne und seine Königswache sich direkt südlich von hier aufhalten sollen.$B$BWir sollten dorthin gehen und in der Masse Schutz suchen.', 'Sprecht mit König Genn Graumähne im Militärviertel.', 'Es war klug von Euch, hierher zu kommen. Wenn die Einwohner von Gilneas zusammenhalten, können wir diesen schrecklichen Feind vielleicht doch noch besiegen.', '', '', '', 0),
(14290, 'deDE', 'Je mehr, desto sicherer', 'Ich habe Euch alles beigebracht, was mir derzeit sinnvoll erscheint.$B$BEs ist an der Zeit, dass wir uns den anderen Überlebenden anschließen. Ich habe gehört, dass König Graumähne und seine Königswache sich direkt südlich von hier aufhalten sollen.$B$BWir sollten dorthin gehen und in der Masse Schutz suchen.', 'Sprecht mit König Genn Graumähne im Militärviertel.', 'Es war klug von Euch, hierher zu kommen. Wenn die Einwohner von Gilneas zusammenhalten, können wir diesen schrecklichen Feind vielleicht doch noch besiegen.', '', '', '', 0),
(14291, 'deDE', 'Je mehr, desto sicherer', 'Ich habe Euch alles beigebracht, was mir derzeit sinnvoll erscheint.$B$BEs ist an der Zeit, dass wir uns den anderen Überlebenden anschließen. Ich habe gehört, dass König Graumähne und seine Königswache sich direkt südlich von hier aufhalten sollen.$B$BWir sollten dorthin gehen und in der Masse Schutz suchen.', 'Sprecht mit König Genn Graumähne im Militärviertel.', 'Es war klug von Euch, hierher zu kommen. Wenn die Einwohner von Gilneas zusammenhalten, können wir diesen schrecklichen Feind vielleicht doch noch besiegen.', '', '', '', 0);

DELETE FROM `quest_template_locale` WHERE `locale` = 'esES' AND `ID` IN (14265, 14266, 14269, 14272, 14273, 14274, 14275, 14276, 14277, 14278, 14279, 14280, 14281, 14283, 14285, 14286, 14287, 14288, 14289, 14290, 14291);
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `OfferRewardText`, `RequestItemsText`, `EndText`, `ObjectiveText1`, `VerifiedBuild`) VALUES
(14265, 'esES', 'Tu instructor', 'La mayoría hemos llegado con vida... pero también hay huargen en este lado de la ciudad.$B$BEn cuanto estemos todos seguiremos dirigiéndonos al sur.$B$BEso me recuerda que alguien preguntaba por ti. Un caballero que responde al nombre de Cleese dijo que eras $g uno:una; de sus estudiantes y quería asegurarse de que estuvieses bien.', 'Habla con el sargento Cleese en el Distrito Militar.', '', '', '', '', 0),
(14266, 'esES', 'Cargar', '¡Estás $g vivo:viva;, $N! Eso debe significar que he hecho algo bien.$B$BLamento que nuestras clases hayan concluido de forma algo prematura. Sin embargo, puede que haya un par de cosas que pueda enseñarte que te serán útiles en un momento como este.$B$BPrueba tu nueva técnica contra los huargen Colmillo de Sangre que hay al oeste.', 'Habla con el sargento Cleese y aprende Cargar. Practica Cargar contra un huargen Colmillo de Sangre.', '', '', '', 'Practica Cargar', 0),
(14269, 'esES', 'Alguien te busca', 'La mayoría hemos llegado con vida... pero también hay huargen en este lado de la ciudad.$B$BEn cuanto estemos todos seguiremos dirigiéndonos al sur.$B$BEso me recuerda que alguien preguntaba por ti. Una mujer llamada Loren... pareció un poco decepcionada cuando le dije que estabas bien.$B$BCreo que dijo algo de que te debe dinero.', 'Habla con Loren la Perista en el Distrito Militar.', '', '', '', '', 0),
(14272, 'esES', 'Eviscerar', '¡Me alegro de verte!$B$BNo, claro que no tengo el dinero que te debo. ¿Ahora no es el momento de eso, no?$B$BEscucha, quizás pueda enseñarte un par de trucos que te salven el pellejo en medio de esta carnicería. Así saldaremos la deuda. ¿Qué me dices?$B$BUna vez completada tu lección, prueba a utilizar tu nueva técnica contra los huargen Colmillo de Sangre que tenemos al oeste.', 'Habla con Loren la Perista y aprende Eviscerar. Practica Eviscerar contra un huargen Colmillo de Sangre.', '', '', '', 'Practica Eviscerar', 0),
(14273, 'esES', 'Asociados umbríos', 'La mayoría hemos llegado con vida... pero también hay huargen en este lado de la ciudad.$B$BEn cuanto estemos todos seguiremos dirigiéndonos al sur.$B$BEso me recuerda que alguien preguntaba por ti. Un caballero peculiar llamado Vitus... Me daba escalofríos.$B$BNo dejaba de hablar de un "conocimiento prohibido" que había descubierto.', 'Habla con Vitus Camino Oscuro en el Distrito Militar.', '', '', '', '', 0),
(14274, 'esES', 'Inmolar', '¡Es cierto! ¡Estás vivo!$B$BNunca tuve la oportunidad de compartir mi gran descubrimiento contigo. A partir de lo más profundo de los libros cuasi-indescifrables de Balcephoth de las sombras viles... He aprendido los secretos prohibidos de...$B$B¡Inmolar!$B$BPor supuesto que compartiré este saber contigo... ¿quién más apreciaría un conocimiento tan poderoso por aquí?$B$BAhora ve y practica tu nuevo hechizo contra los huargen Colmillo de Sangre que tenemos al oeste.', 'Habla con Vitus Camino Oscuro y aprende Inmolar. Practica lanzando Inmolar a un huargen Colmillo de Sangre.', '', '', '', 'Practica Inmolar', 0),
(14275, 'esES', 'Alguien te sigue la pista', 'La mayoría hemos llegado con vida... pero también hay huargen en este lado de la ciudad.$B$BEn cuanto estemos todos seguiremos dirigiéndonos al sur.$B$BEso me recuerda que alguien preguntaba por ti. Un hombre llamado Blake. Dijo algo sobre un plan para huir al bosque.', 'Habla con el montero Blake en el Distrito Militar.', '', '', '', '', 0),
(14276, 'esES', 'Disparo firme', 'Bueno, tengo buenas y malas noticias.$B$BLa mala es que hay más huargen en el bosque que aquí... así que no hay ningún lugar seguro donde poder escondernos.$B$BLa buena es que aún tengo un par de cosas que enseñarte. ¿Quién sabe qué tipo de facultad podría salvarte la vida en un tiempo como este?$B$BPrueba suerte con ella contra los huargen Colmillo de Sangre del oeste.', 'Habla con el montero Blake y aprende Disparo firme. Practica tu Disparo firme dos veces contra un huargen Colmillo de Sangre.', '', '', '', 'Practica Disparo firme', 0),
(14278, 'esES', 'Busca a la hermana', 'La mayoría hemos llegado con vida... pero también hay huargen en este lado de la ciudad.$B$BEn cuanto estemos todos seguiremos dirigiéndonos al sur.$B$BEso me recuerda que alguien preguntaba por ti. La hermana Almyra, que pertenece al clero, dijo que estabas en gran peligro y que necesitabas la protección de la Luz.$B$BDeberías hablar con ella, parecía muy preocupada.', 'Habla con la hermana Almyra en el Distrito Militar.', 'La Luz está contigo, $N. Es un alivio verte.', '', '', '', 0),
(14279, 'esES', 'Sanación relámpago', 'Tienes mucho que aprender, $N. Y yo mucho que enseñarte.$B$BPero vivimos tiempos difíciles y temo que tengamos que acelerar algunas lecciones.$B$BNo tengas miedo, $g hermano:hermana;. La Luz nos guiará por este camino.', 'Habla con la hermana Almyra y aprende Sanación relámpago. Utiliza Sanación relámpago 2 veces con un guardia herido.', '', '', '', 'Practica Sanación relámpago', 0),
(14280, 'esES', 'El viento sabe tu nombre... O eso parece', 'La mayoría hemos llegado con vida... pero también hay huargen en este lado de la ciudad.$B$BEn cuanto estemos todos seguiremos dirigiéndonos al sur.$B$BEso me recuerda que alguien preguntaba por ti. Era la bruja de la cosecha, Celestina. Dijo que los vientos pronunciaron tu nombre.$B$BMejor date prisa, $N. Cuando hayas terminado de comunicarte con la naturaleza nos hará falta que vuelvas a machacar cráneos de huargen.', 'Habla con Celestina de La Cosecha en el Distrito Militar.', '', '', '', '', 0),
(14283, 'esES', 'Un toque de rejuvenecimiento', 'Ya nos llevaron al límite de la extinción antes, $N. Pero nosotros, los druidas, guardianes de los viejos hábitos, salvamos a nuestra gente de la inanición.$B$BCuando nos separamos del mundo exterior y nuestros cultivos dejaron de funcionar, fue nuestra orden la que llamó a las bendiciones de la tierra y recuperó la cosecha.$B$BComo lo hicimos esa vez, lo mejor es poner nuestro destino en manos de un poder superior. Únete a mí y aprende lo que nos tiene que enseñar lo salvaje.', 'Habla con Celestina de la Cosecha y aprende Rejuvenecimiento. Practica Rejuvenecimiento con un guardia herido.', '', '', '', 'Practica Rejuvenecimiento', 0),
(14285, 'esES', 'Cuantos más, mejor', 'No hay mucho que pueda enseñarte ahora que todos estos huargen intentan despedazarnos.$B$BDeberíamos pensar en partir hacia el sur con los otros supervivientes. Nos han dicho que el rey Cringris está allí.$B$BSi nos mantenemos unidos nuestras oportunidades de sobrevivir aumentarán... especialmente si eliges estar al lado de alguien con pinta de estar bien alimentado.', 'Habla con el rey Genn Cringris en el Distrito Militar.', '', '', '', '', 0),
(14286, 'esES', 'Cuantos más, mejor', 'Te he enseñado todo lo necesario por ahora.$B$BEs hora de reunirnos con los demás supervivientes. Mencionaron que el rey Cringris y su guardia real están justo al sur de aquí.$B$BDeberíamos ir allí, donde nuestro número mayor nos servirá de protección.', 'Habla con el rey Genn Cringris en el Distrito Militar.', '', '', '', '', 0),
(14287, 'esES', 'Cuantos más, mejor', 'Te he enseñado todo lo necesario por ahora.$B$BEs hora de reunirnos con los demás supervivientes. Mencionaron que el rey Cringris y su guardia real están justo al sur de aquí.$B$BDeberíamos ir allí, donde nuestro número mayor nos servirá de protección.', 'Habla con el rey Genn Cringris en el Distrito Militar.', '', '', '', '', 0),
(14288, 'esES', 'Cuantos más, mejor', 'No hay mucho que pueda enseñarte ahora que todos estos huargen intentan despedazarnos.$B$BDeberíamos pensar en partir hacia el sur con los otros supervivientes. Nos han dicho que el rey Cringris está allí.$B$BSi nos mantenemos unidos nuestras oportunidades de sobrevivir aumentarán... especialmente si eliges estar al lado de alguien con pinta de estar bien alimentado.', 'Habla con el rey Genn Cringris en el Distrito Militar.', '', '', '', '', 0),
(14289, 'esES', 'Cuantos más, mejor', 'Te he enseñado todo lo necesario por ahora.$B$BEs hora de unirnos a los otros supervivientes. Los demás mencionaron que el Rey Cringris y su guardia real están justo al sur de aquí.$B$BEl resto necesitará la ayuda de la Luz en estos tiempos difíciles.', 'Habla con el rey Genn Cringris en el Distrito Militar.', 'Has hecho bien en venir aquí. Si los gilneanos nos mantenemos unidos, podremos derrotar a este terrible enemigo.', '', '', '', 0),
(14290, 'esES', 'Cuantos más, mejor', 'Te he enseñado todo lo necesario por ahora.$B$BEs hora de reunirnos con los demás supervivientes. Mencionaron que el rey Cringris y su guardia real están justo al sur de aquí.$B$BDeberíamos ir allí, donde nuestro número mayor nos servirá de protección.', 'Habla con el rey Genn Cringris en el Distrito Militar.', '', '', '', '', 0),
(14291, 'esES', 'Cuantos más, mejor', 'Te he enseñado todo lo necesario por ahora.$B$BEs hora de reunirnos con los demás supervivientes. Mencionaron que el rey Cringris y su guardia real están justo al sur de aquí.$B$BDeberíamos ir allí, donde nuestro número mayor nos servirá de protección.', 'Habla con el rey Genn Cringris en el Distrito Militar.', '', '', '', '', 0);

DELETE FROM `quest_template_locale` WHERE `locale` = 'esMX' AND `ID` IN (14265, 14266, 14269, 14272, 14273, 14274, 14275, 14276, 14277, 14278, 14279, 14280, 14281, 14283, 14285, 14286, 14287, 14288, 14289, 14290, 14291);
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `OfferRewardText`, `RequestItemsText`, `EndText`, `ObjectiveText1`, `VerifiedBuild`) VALUES
(14265, 'esMX', 'Tu instructor', 'La mayoría hemos llegado con vida... pero también hay huargen en este lado de la ciudad.$B$BEn cuanto estemos todos seguiremos dirigiéndonos al sur.$B$BEso me recuerda que alguien preguntaba por ti. Un caballero que responde al nombre de Cleese dijo que eras $g uno:una; de sus estudiantes y quería asegurarse de que estuvieses bien.', 'Habla con el sargento Cleese en el Distrito Militar.', '', '', '', '', 0),
(14266, 'esMX', 'Cargar', '¡Estás $g vivo:viva;, $N! Eso debe significar que he hecho algo bien.$B$BLamento que nuestras clases hayan concluido de forma algo prematura. Sin embargo, puede que haya un par de cosas que pueda enseñarte que te serán útiles en un momento como este.$B$BPrueba tu nueva técnica contra los huargen Colmillo de Sangre que hay al oeste.', 'Habla con el sargento Cleese y aprende Cargar. Practica Cargar contra un huargen Colmillo de Sangre.', '', '', '', 'Practica Cargar', 0),
(14269, 'esMX', 'Alguien te busca', 'La mayoría hemos llegado con vida... pero también hay huargen en este lado de la ciudad.$B$BEn cuanto estemos todos seguiremos dirigiéndonos al sur.$B$BEso me recuerda que alguien preguntaba por ti. Una mujer llamada Loren... pareció un poco decepcionada cuando le dije que estabas bien.$B$BCreo que dijo algo de que te debe dinero.', 'Habla con Loren la Perista en el Distrito Militar.', '', '', '', '', 0),
(14272, 'esMX', 'Eviscerar', '¡Me alegro de verte!$B$BNo, claro que no tengo el dinero que te debo. ¿Ahora no es el momento de eso, no?$B$BEscucha, quizás pueda enseñarte un par de trucos que te salven el pellejo en medio de esta carnicería. Así saldaremos la deuda. ¿Qué me dices?$B$BUna vez completada tu lección, prueba a utilizar tu nueva técnica contra los huargen Colmillo de Sangre que tenemos al oeste.', 'Habla con Loren la Perista y aprende Eviscerar. Practica Eviscerar contra un huargen Colmillo de Sangre.', '', '', '', 'Practica Eviscerar', 0),
(14273, 'esMX', 'Asociados umbríos', 'La mayoría hemos llegado con vida... pero también hay huargen en este lado de la ciudad.$B$BEn cuanto estemos todos seguiremos dirigiéndonos al sur.$B$BEso me recuerda que alguien preguntaba por ti. Un caballero peculiar llamado Vitus... Me daba escalofríos.$B$BNo dejaba de hablar de un "conocimiento prohibido" que había descubierto.', 'Habla con Vitus Camino Oscuro en el Distrito Militar.', '', '', '', '', 0),
(14274, 'esMX', 'Inmolar', '¡Es cierto! ¡Estás vivo!$B$BNunca tuve la oportunidad de compartir mi gran descubrimiento contigo. A partir de lo más profundo de los libros cuasi-indescifrables de Balcephoth de las sombras viles... He aprendido los secretos prohibidos de...$B$B¡Inmolar!$B$BPor supuesto que compartiré este saber contigo... ¿quién más apreciaría un conocimiento tan poderoso por aquí?$B$BAhora ve y practica tu nuevo hechizo contra los huargen Colmillo de Sangre que tenemos al oeste.', 'Habla con Vitus Camino Oscuro y aprende Inmolar. Practica lanzando Inmolar a un huargen Colmillo de Sangre.', '', '', '', 'Practica Inmolar', 0),
(14275, 'esMX', 'Alguien te sigue la pista', 'La mayoría hemos llegado con vida... pero también hay huargen en este lado de la ciudad.$B$BEn cuanto estemos todos seguiremos dirigiéndonos al sur.$B$BEso me recuerda que alguien preguntaba por ti. Un hombre llamado Blake. Dijo algo sobre un plan para huir al bosque.', 'Habla con el montero Blake en el Distrito Militar.', '', '', '', '', 0),
(14276, 'esMX', 'Disparo firme', 'Bueno, tengo buenas y malas noticias.$B$BLa mala es que hay más huargen en el bosque que aquí... así que no hay ningún lugar seguro donde poder escondernos.$B$BLa buena es que aún tengo un par de cosas que enseñarte. ¿Quién sabe qué tipo de facultad podría salvarte la vida en un tiempo como este?$B$BPrueba suerte con ella contra los huargen Colmillo de Sangre del oeste.', 'Habla con el montero Blake y aprende Disparo firme. Practica tu Disparo firme dos veces contra un huargen Colmillo de Sangre.', '', '', '', 'Practica Disparo firme', 0),
(14278, 'esMX', 'Busca a la hermana', 'La mayoría hemos llegado con vida... pero también hay huargen en este lado de la ciudad.$B$BEn cuanto estemos todos seguiremos dirigiéndonos al sur.$B$BEso me recuerda que alguien preguntaba por ti. La hermana Almyra, que pertenece al clero, dijo que estabas en gran peligro y que necesitabas la protección de la Luz.$B$BDeberías hablar con ella, parecía muy preocupada.', 'Habla con la hermana Almyra en el Distrito Militar.', 'La Luz está contigo, $N. Es un alivio verte.', '', '', '', 0),
(14279, 'esMX', 'Sanación relámpago', 'Tienes mucho que aprender, $N. Y yo mucho que enseñarte.$B$BPero vivimos tiempos difíciles y temo que tengamos que acelerar algunas lecciones.$B$BNo tengas miedo, $g hermano:hermana;. La Luz nos guiará por este camino.', 'Habla con la hermana Almyra y aprende Sanación relámpago. Utiliza Sanación relámpago 2 veces con un guardia herido.', '', '', '', 'Practica Sanación relámpago', 0),
(14280, 'esMX', 'El viento sabe tu nombre... O eso parece', 'La mayoría hemos llegado con vida... pero también hay huargen en este lado de la ciudad.$B$BEn cuanto estemos todos seguiremos dirigiéndonos al sur.$B$BEso me recuerda que alguien preguntaba por ti. Era la bruja de la cosecha, Celestina. Dijo que los vientos pronunciaron tu nombre.$B$BMejor date prisa, $N. Cuando hayas terminado de comunicarte con la naturaleza nos hará falta que vuelvas a machacar cráneos de huargen.', 'Habla con Celestina de La Cosecha en el Distrito Militar.', '', '', '', '', 0),
(14283, 'esMX', 'Un toque de rejuvenecimiento', 'Ya nos llevaron al límite de la extinción antes, $N. Pero nosotros, los druidas, guardianes de los viejos hábitos, salvamos a nuestra gente de la inanición.$B$BCuando nos separamos del mundo exterior y nuestros cultivos dejaron de funcionar, fue nuestra orden la que llamó a las bendiciones de la tierra y recuperó la cosecha.$B$BComo lo hicimos esa vez, lo mejor es poner nuestro destino en manos de un poder superior. Únete a mí y aprende lo que nos tiene que enseñar lo salvaje.', 'Habla con Celestina de la Cosecha y aprende Rejuvenecimiento. Practica Rejuvenecimiento con un guardia herido.', '', '', '', 'Practica Rejuvenecimiento', 0),
(14285, 'esMX', 'Cuantos más, mejor', 'No hay mucho que pueda enseñarte ahora que todos estos huargen intentan despedazarnos.$B$BDeberíamos pensar en partir hacia el sur con los otros supervivientes. Nos han dicho que el rey Cringris está allí.$B$BSi nos mantenemos unidos nuestras oportunidades de sobrevivir aumentarán... especialmente si eliges estar al lado de alguien con pinta de estar bien alimentado.', 'Habla con el rey Genn Cringris en el Distrito Militar.', '', '', '', '', 0),
(14286, 'esMX', 'Cuantos más, mejor', 'Te he enseñado todo lo necesario por ahora.$B$BEs hora de reunirnos con los demás supervivientes. Mencionaron que el rey Cringris y su guardia real están justo al sur de aquí.$B$BDeberíamos ir allí, donde nuestro número mayor nos servirá de protección.', 'Habla con el rey Genn Cringris en el Distrito Militar.', '', '', '', '', 0),
(14287, 'esMX', 'Cuantos más, mejor', 'Te he enseñado todo lo necesario por ahora.$B$BEs hora de reunirnos con los demás supervivientes. Mencionaron que el rey Cringris y su guardia real están justo al sur de aquí.$B$BDeberíamos ir allí, donde nuestro número mayor nos servirá de protección.', 'Habla con el rey Genn Cringris en el Distrito Militar.', '', '', '', '', 0),
(14288, 'esMX', 'Cuantos más, mejor', 'No hay mucho que pueda enseñarte ahora que todos estos huargen intentan despedazarnos.$B$BDeberíamos pensar en partir hacia el sur con los otros supervivientes. Nos han dicho que el rey Cringris está allí.$B$BSi nos mantenemos unidos nuestras oportunidades de sobrevivir aumentarán... especialmente si eliges estar al lado de alguien con pinta de estar bien alimentado.', 'Habla con el rey Genn Cringris en el Distrito Militar.', '', '', '', '', 0),
