(14290, 'esMX', 'Cuantos más, mejor', 'Te he enseñado todo lo necesario por ahora.$B$BEs hora de reunirnos con los demás supervivientes. Mencionaron que el rey Cringris y su guardia real están justo al sur de aquí.$B$BDeberíamos ir allí, donde nuestro número mayor nos servirá de protección.', 'Habla con el rey Genn Cringris en el Distrito Militar.', '', '', '', '', 0),
(14291, 'esMX', 'Cuantos más, mejor', 'Te he enseñado todo lo necesario por ahora.$B$BEs hora de reunirnos con los demás supervivientes. Mencionaron que el rey Cringris y su guardia real están justo al sur de aquí.$B$BDeberíamos ir allí, donde nuestro número mayor nos servirá de protección.', 'Habla con el rey Genn Cringris en el Distrito Militar.', '', '', '', '', 0);

DELETE FROM `quest_template_locale` WHERE `locale` = 'frFR' AND `ID` IN (14265, 14266, 14269, 14272, 14273, 14274, 14275, 14276, 14277, 14278, 14279, 14280, 14281, 14283, 14285, 14286, 14287, 14288, 14289, 14290, 14291);
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `OfferRewardText`, `RequestItemsText`, `EndText`, `ObjectiveText1`, `VerifiedBuild`) VALUES
(14265, 'frFR', 'Votre instructeur', 'On s’en est presque tous sortis vivants... mais il y a aussi des worgens de ce côté de la ville.$B$BOn continuera vers le sud quand on aura rassemblé tout le monde.$B$BÇa me fait penser que quelqu''un m''a demandé de vos nouvelles : un type qui disait s’appeler Cleese dont vous seriez l’$g un:une; des $g étudiants:étudiantes;. Il voulait s''assurer que vous alliez bien.', 'Parlez au Sergent Cleese dans le Secteur Militaire.', '', '', '', '', 0),
(14266, 'frFR', 'À la charge !', 'Vous êtes toujours en vie, $N ! Ça en dit long sur mon enseignement !$B$BEt encore, nos leçons ont été interrompues. Mais je peux peut-être quand même vous apprendre une ou deux petites choses que vous trouverez sûrement bien pratiques par les temps qui courent.$B$BAllez donc essayer ces nouvelles techniques contre les worgens croc-de-sang qui sont à l’ouest.', 'Parlez au Sergent Cleese qui vous enseignera la Charge. Ensuite, exercez-vous à utiliser la Charge contre un Worgen croc-de-sang.', '', '', '', 'S’exercer à la Charge', 0),
(14269, 'frFR', 'Quelqu''un vous cherche', 'On s’en est presque tous sortis vivants... mais il y a aussi des worgens de ce côté de la ville.$B$BOn continuera vers le sud quand on aura rassemblé tout le monde.$B$BÇa me fait penser que quelqu''un m''a demandé de vos nouvelles : une femme qui disait s’appeler Loren... Elle a eu l’air un peu déçu quand je lui ai dit que vous alliez bien.$B$BJe crois qu''elle a parlé d''argent qu''elle vous devait.', 'Parlez à Loren la Receleuse dans le Secteur Militaire.', '', '', '', '', 0),
(14272, 'frFR', 'L''éviscération', 'Je suis heureuse de voir que vous êtes $g vivant:vivante; !$B$BBien sûr que non, je n''ai pas l''or que je vous dois. Vous croyez vraiment que c’est le moment de parler de ça ?$B$BJ’ai une idée ! Je peux vous apprendre un truc ou deux qui pourraient vous sauver la peau au milieu de tout ce carnage. Je dirais qu’avec ça, on sera quitte, vous et moi. Vous en dites quoi ?$B$BQuand la leçon sera finie, vous devriez essayer vos nouvelles techniques contre les worgens croc-de-sang qui sont à l’ouest.', 'Parlez à Loren la Receleuse qui vous enseignera l''Éviscération. Ensuite, exercez-vous à utiliser l''Éviscération contre un Worgen croc-de-sang.', '', '', '', 'S’exercer à l’Éviscération', 0),
(14273, 'frFR', 'D''obscurs associés', 'On s’en est presque tous sortis vivants... mais il y a aussi des worgens de ce côté de la ville.$B$BOn continuera vers le sud quand on aura rassemblé tout le monde.$B$BÇa me fait penser que quelqu''un m''a demandé de vos nouvelles : un type bizarre qui disait s’appeler Vitus... Il m''a donné la chair de poule.$B$BIl n''arrêtait pas de parler de « savoir interdit » qu''il avait découvert.', 'Parlez à Vitus Sombremarcheur dans le Secteur Militaire.', 'Les ténèbres se sont abattues sur nos terres. Et pas vraiment des ténèbres dans notre genre, si vous voyez ce que je veux dire.', '', '', '', 0),
(14274, 'frFR', 'L''immolation', 'Alors c''était vrai ! Vous êtes $g vivant:vivante; !$B$BJe n''ai jamais eu l''occasion de vous mettre au courant de ma plus grande découverte. Caché au fin fond des pages quasiment indéchiffrables des livres de Balcephoth des gangrombres... j''ai trouvé le secret interdit de...$B$Bl''immolation !$B$BBien sûr que je vais partager ma découverte avec vous... Qui d''autre dans les alentours serait capable d’appréhender un savoir d’une telle puissance ?$B$BEt maintenant, vous devriez vous exercer à lancer votre nouveau sort contre les worgens croc-de-sang qui sont à l’ouest.', 'Parlez à Vitus Sombremarcheur qui vous enseignera l''Immolation. Ensuite, exercez-vous à lancer l’Immolation contre un Worgen croc-de-sang.', 'Oui ! Vous sentez cette puissance, pas vrai ?', '', '', 'S''exercer à l''Immolation', 0),
(14275, 'frFR', 'Quelqu''un vous suit à la trace', 'On s’en est presque tous sortis vivants... mais il y a aussi des worgens de ce côté de la ville.$B$BOn continuera vers le sud quand on aura rassemblé tout le monde.$B$BÇa me fait penser que quelqu''un m''a demandé de vos nouvelles : un type qui disait s’appeler Blake. Il a marmonné quelque chose à propos d''un plan pour s''échapper par les bois.', 'Parlez au Veneur Blake dans le Secteur Militaire.', '$N ! J’étais sûr que vous étiez dans le coin.', '', '', '', 0),
(14276, 'frFR', 'Le tir assuré', 'J''ai une bonne et une mauvaise nouvelle.$B$BLa mauvaise, c''est que les bois sont encore plus infestés de worgens que la ville... Du coup, on n’a aucun endroit sûr où se planquer.$B$BLa bonne nouvelle, c''est que j''ai encore une ou deux petites choses à vous apprendre. Dans les circonstances présentes, bien malin qui pourrait dire quelle compétence vous sauvera.$B$BFaites-vous la main en vous exerçant contre les worgens croc-de-sang à l’ouest.', 'Parlez au Veneur Blake qui vous enseignera le Tir assuré. Ensuite, exercez-vous au Tir assuré 2 fois contre un Worgen croc-de-sang.', 'Excellent travail, $N. Ces worgens vont regretter d''avoir jamais posé la patte sur nos terres.', 'Vous apprenez vite. Nous allons montrer à ces worgens ce que c’est qu’un vrai $c.', '', 'S’exercer au Tir assuré', 0),
(14277, 'frFR', 'Enquêtes arcaniques', 'On s’en est presque tous sortis vivants... mais il y a aussi des worgens de ce côté de la ville.$B$BOn continuera vers le sud quand on aura rassemblé tout le monde.$B$BÇa me fait penser que quelqu''un m''a demandé de vos nouvelles : une femme, une mage apparemment, qui disait s’appeler Myriam. Elle vous fait dire qu’il faut se tenir prêt, ou quelque chose comme ça.', 'Parlez à Myriam Éveillesort dans le Secteur Militaire.', 'Un disciple des Arcanes trouve toujours le moyen d''avancer. Je suis heureuse de vous voir, $N.', '', '', '', 0),
(14278, 'frFR', 'Cherchez la sœur', 'On s’en est presque tous sortis vivants... mais il y a aussi des worgens de ce côté de la ville.$B$BOn continuera vers le sud quand on aura rassemblé tout le monde.$B$BÇa me fait penser que quelqu''un m''a demandé de vos nouvelles : un membre du clergé, une sœur, qui disait s’appeler Almyra. Elle vous fait dire que vous courez un grave danger et que vous auriez grand besoin de la protection de la Lumière.$B$BVous devriez aller lui parler, elle avait l’air vraiment très inquiet.', 'Parlez à Sœur Almyra dans le Secteur Militaire.', 'Je sais que la Lumière est avec vous, $N, mais je suis quand même soulagée de vous voir.', '', '', '', 0),
(14279, 'frFR', 'Soins rapides', 'Vous avez beaucoup à apprendre, $N. Et j''ai de nombreuses choses à vous enseigner.$B$BCependant, nous vivons des temps troublés, et j''ai bien peur que nous devions accélérer vos leçons.$B$BNe craignez rien, $g mon frère:ma sœur;. La Lumière nous guidera à travers cette épreuve.', 'Parlez à Sœur Almyra qui vous enseignera les Soins rapides. Ensuite, utilisez les Soins rapides 2 fois sur un Garde blessé.', 'Vous êtes béni, $N. La Lumière vous auréole, même dans ces heures sombres.', '', '', 'S’exercer aux Soins rapides', 0),
(14280, 'frFR', 'Les vents connaissent votre nom... apparemment', 'On s’en est presque tous sortis vivants... mais il y a aussi des worgens de ce côté de la ville.$B$BOn continuera vers le sud quand on aura rassemblé tout le monde.$B$BÇa me fait penser que quelqu''un m''a demandé de vos nouvelles : c’était cette sorcière des moissons, vous savez, Célestine. Elle vous fait dire que les vents parlent de vous.$B$BVous feriez mieux de filer la voir, $N. Mais il faudra que vous reveniez très vite nous aider à massacrer du worgen, une fois que vous en aurez terminé avec votre petite conversation avec la nature.', 'Parlez à Célestine de la Moisson dans le Secteur Militaire.', 'Vous avez été béni aujourd''hui. Vous êtes vivant et en bonne santé !', '', '', '', 0),
(14281, 'frFR', 'Les projectiles des Arcanes', 'Une dure tâche nous attend, $N. Nous devrons lui consacrer toute notre puissance mentale sans restriction.$B$BNéanmoins, il arrive que cela ne soit pas suffisant. Oui, il arrive que l’on doive avoir recours à des méthodes plus brutales.$B$BIl se trouve que j’ai en tête un sort parfait dans une telle situation et je serais plus que ravie d’en partager le secret avec vous. Quand vous l’aurez appris, vous vous exercerez à le lancer contre les worgens croc-de-sang qui sont à l’ouest. Vous ne pourrez faire usage de votre nouveau sort uniquement après en avoir lancé un autre auparavant.', 'Parlez à Myriam Éveillesort qui vous enseignera les Projectiles des Arcanes. Ensuite, lancez des Projectiles des Arcanes contre un Worgen croc-de-sang.', 'Vous apprenez avec une telle aisance et si rapidement. Bientôt, ce sera vous l''enseignant.', 'J''ai toujours su que vous aviez l''esprit vif.', '', 'S''exercer avec les Projectiles des Arcanes', 0),
(14283, 'frFR', 'Récupération', 'Nous avons déjà failli connaître l''extinction de notre nation, $N. Mais nous autres druides, gardiens des anciennes traditions, avons sauvé notre peuple de la famine.$B$BLorsque nous nous sommes coupés du monde et que nos récoltes n''ont rien donné, c''est notre ordre qui en a appelé à la bénédiction de la terre pour sauver la moisson.$B$BComme nous l''avons déjà fait, il est plus sage de remettre notre destin dans les mains de puissances supérieures. Joignez-vous à moi et apprenez ce que la nature a à vous enseigner.', 'Allez voir Célestine de la Moisson qui vous enseignera Récupération. Ensuite, exercez-vous à utiliser Récupération 2 fois sur un Garde blessé.', 'Pas mal du tout. Les anciennes traditions ont peut-être encore leur place.', 'La terre nous parle, $N. Elle ne nous abandonnera pas, même en ces temps difficiles.', '', 'S''exercer à utiliser Récupération', 0),
(14285, 'frFR', 'Le groupe apporte la sécurité', 'Il y a des limites à ce que je peux vous enseigner tant que ces worgens tenteront de nous démembrer.$B$BNous devrions envisager de partir vers le sud avec les autres survivants. On nous a dit que le roi Grisetête était déjà là-bas.$B$BSi nous restons ensemble, nos chances de survie augmenteront... surtout si l''on choisit de rester avec quelqu''un qui a l''air plus... appétissant.', 'Parlez au Roi Genn Grisetête dans le Secteur Militaire.', 'Vous avez bien fait de venir ici. Si le peuple gilnéen reste soudé, nous arriverons finalement à vaincre ce terrible ennemi.', '', '', '', 0),
(14286, 'frFR', 'Le groupe apporte la sécurité', 'Je vous ai appris tout ce dont vous avez besoin pour l''instant.$B$BNous devons rejoindre les autres survivants. Les autres ont dit que le roi Grisetête et sa garde royale se trouvent juste au sud.$B$BNous devrions aller là-bas. Nous serons plus en sécurité en étant tous réunis.', 'Parlez au Roi Genn Grisetête dans le Secteur Militaire.', '', '', '', '', 0),
(14287, 'frFR', 'Le groupe apporte la sécurité', 'Je vous ai appris tout ce dont vous avez besoin pour l''instant.$B$BNous devons rejoindre les autres survivants. Les autres ont dit que le roi Grisetête et sa garde royale se trouvent juste au sud.$B$BNous devrions aller là-bas. Nous serons plus en sécurité en étant tous réunis.', 'Parlez au Roi Genn Grisetête dans le Secteur Militaire.', '', '', '', '', 0),
(14288, 'frFR', 'Le groupe apporte la sécurité', 'Il y a des limites à ce que je peux vous enseigner tant que ces worgens tenteront de nous démembrer.$B$BNous devrions envisager de partir vers le sud avec les autres survivants. On nous a dit que le roi Grisetête était déjà là-bas.$B$BSi nous restons ensemble, nos chances de survie augmenteront... surtout si l''on choisit de rester avec quelqu''un qui a l''air plus... appétissant.', 'Parlez au Roi Genn Grisetête dans le Secteur Militaire.', 'Vous avez bien fait de venir ici. Si le peuple gilnéen reste soudé, nous arriverons finalement à vaincre ce terrible ennemi.', '', '', '', 0),
(14289, 'frFR', 'Le groupe apporte la sécurité', 'Je vous ai appris tout ce dont vous avez besoin pour l''instant.$B$BNous devons rejoindre les autres survivants. Les autres ont dit que le roi Grisetête et sa garde royale se trouvent juste au sud.$B$BLes survivants vont avoir besoin de l''aide de la Lumière en ces temps troublés.', 'Parlez au Roi Genn Grisetête dans le Secteur Militaire.', 'Vous avez bien fait de venir ici. Si le peuple gilnéen reste soudé, nous arriverons finalement à vaincre ce terrible ennemi.', '', '', '', 0),
(14290, 'frFR', 'Le groupe apporte la sécurité', 'Je vous ai appris tout ce dont vous avez besoin pour l''instant.$B$BNous devons rejoindre les autres survivants. Les autres ont dit que le roi Grisetête et sa garde royale se trouvent juste au sud.$B$BNous devrions aller là-bas. Nous serons plus en sécurité en étant tous réunis.', 'Parlez au Roi Genn Grisetête dans le Secteur Militaire.', '', '', '', '', 0),
(14291, 'frFR', 'Le groupe apporte la sécurité', 'Je vous ai appris tout ce dont vous avez besoin pour l''instant.$B$BNous devons rejoindre les autres survivants. Les autres ont dit que le roi Grisetête et sa garde royale se trouvent juste au sud.$B$BNous devrions aller là-bas. Nous serons plus en sécurité en étant tous réunis.', 'Parlez au Roi Genn Grisetête dans le Secteur Militaire.', '', '', '', '', 0);

DELETE FROM `quest_template_locale` WHERE `locale` = 'ruRU' AND `ID` IN (14265, 14266, 14269, 14272, 14273, 14274, 14275, 14276, 14277, 14278, 14279, 14280, 14281, 14283, 14285, 14286, 14287, 14288, 14289, 14290, 14291);
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `OfferRewardText`, `RequestItemsText`, `EndText`, `ObjectiveText1`, `VerifiedBuild`) VALUES
(14265, 'ruRU', 'Твой наставник', 'Большинство жителей без проблем добрались до другой части города... но оказалось, что здесь тоже водятся воргены.$B$BМы намереваемся двигаться дальше на юг, как только пересчитаем людей.$B$BКстати, чуть не забыла – тебя искал один человек. Некий Клиз утверждает, что был твоим наставником, и он хочет убедиться, что с тобой все в порядке.', 'Поговорите с сержантом Клизом в Военном квартале.', '', '', '', '', 0),
(14266, 'ruRU', 'Рывок', 'Ты $g уцелел:уцелела;, $N! Значит, я хорошо тебя обучил.$B$BЖаль, что наши занятия пришлось прервать – но, если хочешь, я покажу тебе еще парочку приемов, которые могут спасти тебе жизнь в это непростое время.$B$BИспытай свои новые умения на воргенах стаи Кровавых Клыков, что обитают на западе.', 'Поговорите с сержантом Клизом и выучите способность "Рывок". Затем используйте ее на воргене из стаи Кровавых Клыков.', 'Прекрасно!', '', '', 'Попрактикуйте "Рывок"', 0),
(14269, 'ruRU', 'Кто-то ищет тебя', 'Большинство жителей без проблем добрались до другой части города... но оказалось, что здесь тоже водятся воргены.$B$BМы намереваемся двигаться дальше на юг, как только пересчитаем людей.$B$BКстати, чуть не забыла – тебя искала какая-то женщина. Некая Лорен... кажется, она расстроилась, узнав, что ты $g уцелел:уцелела;. По-моему, она упомянула, что должна тебе денег.', 'Поговорите с Лорен Укрывательницей в Военном квартале.', 'Ой, привет! А вот и ты!', '', '', '', 0),
(14272, 'ruRU', 'Потрошение', 'Как я рада видеть тебя $g живым и невредимым:живой и невредимой;! $B$BНет, у меня при себе нет твоего золота. $g Сам:Сама; понимаешь, сейчас не время припоминать старые долги.$B$BПослушай, давай я лучше покажу тебе парочку приемов, которые могут спасти тебе шкуру в эти неспокойные времена. Согласись, это гораздо полезнее денег.$B$BА когда мы закончим урок, ты сможешь применить новые знания против воргенов из стаи Кровавых Клыков, что водятся на западе отсюда.', 'Поговорите с Лорен Укрывательницей и выучите способность "Потрошение". Затем убейте с помощью этой способности воргена из стаи Кровавых Клыков.', 'Не старайся прыгнуть выше головы. Просто помни все, чему я тебя научила.$B$BА теперь давай посмотрим, удастся ли нам выбраться из города целыми и невредимыми.', '', '', 'Попрактикуйте "Потрошение"', 0),
(14273, 'ruRU', 'Странные знакомства', 'Большинство жителей без проблем добрались до другой части города... но оказалось, что здесь тоже водятся воргены.$B$BМы намереваемся двигаться дальше на юг, как только пересчитаем людей.$B$BКстати, чуть не забыла – тебя искал какой-то странный парень по имени Вит... жуткий тип, у меня от него мурашки по коже.$B$BОн все говорил о каком-то запретном знании.', 'Поговорите с Витом Дарквокером в Военном квартале.', '', '', '', '', 0),
(14274, 'ruRU', 'Жертвенный огонь', 'Значит, это правда! Ты $g уцелел:уцелела;!$B$BЯ уж боялся, что мне никогда больше не представится случай поделиться с тобой моим величайшим открытием. Послушай: из запретных книг Балсефота, скрытых среди демонических теней... Расшифровав сложнейшие тайнописи, я узнал великую тайну...$B$BЖертвенного огня!$B$BНу конечно, я поделюсь этим знанием с тобой... разве ты видишь здесь кого-то еще, кто мог бы оценить красоту и мощь подобного заклинания?$B$BА теперь иди и испробуй его на воргенах из стаи Кровавых Клыков, что водятся на западе.', 'Поговорите с Витом Дарквокером и выучите заклинание "Жертвенный огонь". Потренируйтесь применять это заклинание на воргенах из стаи Кровавых Клыков.', '', '', '', 'Попрактикуйте "Жертвенный огонь"', 0),
(14275, 'ruRU', 'Кто-то следит за тобой', 'Большинство жителей без проблем добрались до другой части города... но оказалось, что здесь тоже водятся воргены.$B$BМы намереваемся двигаться дальше на юг, как только пересчитаем людей.$B$BКстати, чуть не забыла – тебя искал какой-то человек по имени Блейк. Сказал, что собирается искать спасения в лесах.', 'Поговорите с ловчим Блейком в Военном квартале.', '$N! Я так и знал, что найду тебя где-то здесь.', '', '', '', 0),
(14276, 'ruRU', 'Верный выстрел', 'Так, у меня для тебя есть хорошая и плохая новость.$B$BПлохая заключается в том, что в местных лесах воргенов еще больше, чем здесь... так что, по сути, спасаться нам негде.$B$BА хорошая новость – я все еще могу научить тебя кое-чему полезному. Кто знает, какие знания спасут нам жизнь в это нелегкое время...$B$BИспытай-ка новые навыки на воргенах из стаи Кровавых Клыков, что водятся на западе.', 'Поговорите с ловчим Блейком и обучитесь способности "Верный выстрел". Затем убейте с ее помощью двух воргенов из стаи Кровавых Клыков.', 'Очень хорошо, $N. Скоро воргены пожалеют о том, что ступили на эти земли.', '', '', 'Попрактикуйте "Верный выстрел"', 0),
(14277, 'ruRU', 'Зов магии', 'Большинство жителей без проблем добрались до другой части города... но оказалось, что здесь тоже водятся воргены.$B$BМы намереваемся двигаться дальше на юг, как только пересчитаем людей.$B$BКстати, чуть не забыла – тебя искала какая-то волшебница по имени Мириам. Странная она, сказала что-то про то, что ты $g должен быть готов:должна быть готова;...', 'Поговорите с Мириам Пробудительницей Чар в Военном квартале.', '', '', '', '', 0),
(14278, 'ruRU', 'В поисках сестры', 'Большинство жителей без проблем добрались до другой части города... но оказалось, что здесь тоже водятся воргены.$B$BМы намереваемся двигаться дальше на юг, как только пересчитаем людей.$B$BКстати, чуть не забыла – тебя искала сестра Альмира, одна из священнослужительниц. Она сказала, что тебе угрожает опасность, и только Свет может защитить тебя от неминуемой смерти.$B$BПо-моему, тебе надо с ней поговорить – она была очень обеспокоена.', 'Поговорите с сестрой Альмирой в Военном квартале.', '', '', '', '', 0),
(14279, 'ruRU', 'Быстрое исцеление', 'Тебе еще многое предстоит познать, $N, а я многому должна тебя научить.$B$BУвы, в эти тяжелые времена я вынуждена перейти сразу к самому главному уроку.$B$BНе бойся, $g брат мой:сестра моя;: Свет укажет нам путь.', 'Поговорите с сестрой Альмирой и выучите заклинание "Быстрое исцеление". Примените его дважды к раненому стражу.', '', '', '', 'Попрактикуйте "Быстрое исцеление"', 0),
(14280, 'ruRU', 'Ветра шепчут твое имя', 'Большинство жителей без проблем добрались до другой части города... но оказалось, что здесь тоже водятся воргены.$B$BМы намереваемся двигаться дальше на юг, как только пересчитаем людей.$B$BКстати, чуть не забыла – тебя искала женщина-друид по имени Целестина. Сказала, что ветра прошептали ей твое имя.$B$BЧепуха какая-то, честное слово.', 'Поговорите с Целестиной Урожайной в Военном квартале.', 'Благословение богам! Ты жив и в добром здравии!', '', '', '', 0),
(14281, 'ruRU', 'Чародейские стрелы', 'Нас ждут нелегкие испытания, $N, и на этом пути потребуется вся сила духа, которой ты располагаешь.$B$BИногда даже этого оказывается недостаточно, и тогда приходится прибегать к огневой мощи.$B$BЯ знаю одно заклинание, которое может выручить тебя в подобной ситуации. Когда ты выучишь его, примени свои знания на практике и убей несколько воргенов из стаи Кровавых Клыков, что водятся на западе. Но помни, что новое заклинание получится использовать только после того, как ты применишь другое.', 'Поговорите с Мириам Пробудительницей Чар и выучите заклинание "Чародейские стрелы". Убейте с его помощью воргена из стаи Кровавых Клыков.', 'Ты так легко усваиваешь новые знания, что вскоре мне придется уступить тебе место учителя.', '', '', 'Попрактикуйте "Чародейские стрелы"', 0),
(14283, 'ruRU', 'Омоложение', 'Наш народ и раньше пребывал на грани полного истребления, $N. Но тогда именно мы, друиды, хранители древнего знания, спасли всех от голодной смерти.$B$BКогда наше королевство отгородилось от остального мира, выдался особо неурожайный год. Но мы воззвали к милости земли, и она одарила нас щедрыми посевами.$B$BНынче мы тоже должны положиться на высшие силы. Подойди же ко мне и узнай, чему может научить природа.', 'Поговорите с Целестиной Урожайной и выучите заклинание "Омоложение". Воспользуйтесь им, чтобы помочь раненому стражу.', 'Неплохо, неплохо. Возможно, у нас еще есть надежда...', 'Земля взывает к нам, $N. И в эти тяжелые времена она не оставит нас без своей заботы.', '', 'Попрактикуйте "Омоложение"', 0),
(14285, 'ruRU', 'Спасение в единстве', 'Боюсь, это все, чему я могу научить тебя сейчас, когда воргены буквально дышат нам в затылок.$B$BТеперь нам надо присоединиться к другим беженцам и направиться на юг. Нам сообщили, что там нас ждет король Седогрив.$B$BЕсли мы будем держаться вместе, то сможем выжить... особенно если ты сможешь прицепиться к кому-нибудь посильнее.', 'Поговорите с королем Генном Седогривом в Военном квартале.', 'Ты правильно поступил, придя сюда. Если все жители Гилнеаса будут держаться вместе, никакой враг нас не одолеет.', '', '', '', 0),
(14286, 'ruRU', 'Спасение в единстве', 'Теперь ты $g обучился:обучилась; всему, что может сохранить тебе жизнь в эти нелегкие дни.$B$BНам пора присоединиться к остальным беженцам. Кажется, кто-то упомянул, что на юге нас ждет король Седогрив со своей верной стражей.$B$BМы должны идти туда, ибо в единстве наше спасение.', 'Поговорите с королем Генном Седогривом в Военном квартале.', 'Ты правильно поступил, придя сюда. Если все жители Гилнеаса будут держаться вместе, никакой враг нас не одолеет.', '', '', '', 0),
(14287, 'ruRU', 'Спасение в единстве', 'Теперь ты $g обучился:обучилась; всему, что может сохранить тебе жизнь в эти нелегкие дни.$B$BНам пора присоединиться к остальным беженцам. Кажется, кто-то упомянул, что на юге нас ждет король Седогрив со своей верной стражей.$B$BМы должны идти туда, ибо в единстве наше спасение.', 'Поговорите с королем Генном Седогривом в Военном квартале.', 'Ты правильно поступил, придя сюда. Если все жители Гилнеаса будут держаться вместе, никакой враг нас не одолеет.', '', '', '', 0),
(14288, 'ruRU', 'Спасение в единстве', 'Боюсь, это все, чему я могу научить тебя сейчас, когда воргены буквально дышат нам в затылок.$B$BТеперь нам надо присоединиться к другим беженцам и направиться на юг. Нам сообщили, что там нас ждет король Седогрив.$B$BЕсли мы будем держаться вместе, то сможем выжить... особенно если ты сможешь прицепиться к кому-нибудь посильнее.', 'Поговорите с королем Генном Седогривом в Военном квартале.', 'Ты правильно поступил, придя сюда. Если все жители Гилнеаса будут держаться вместе, никакой враг нас не одолеет.', '', '', '', 0),
(14289, 'ruRU', 'Спасение в единстве', 'Теперь ты $g обучился:обучилась; всему, что может сохранить тебе жизнь в эти нелегкие дни.$B$BНам пора присоединиться к остальным беженцам. Кажется, кто-то упомянул, что на юге нас ждет король Седогрив со своей верной стражей.$B$BМы должны идти туда, ибо в единстве наше спасение.', 'Поговорите с королем Генном Седогривом в Военном квартале.', '', '', '', '', 0),
(14290, 'ruRU', 'Спасение в единстве', 'Теперь ты $g обучился:обучилась; всему, что может сохранить тебе жизнь в эти нелегкие дни.$B$BНам пора присоединиться к остальным беженцам. Кажется, кто-то упомянул, что на юге нас ждет король Седогрив со своей верной стражей.$B$BМы должны идти туда, ибо в единстве наше спасение.', 'Поговорите с королем Генном Седогривом в Военном квартале.', 'Ты правильно поступил, придя сюда. Если все жители Гилнеаса будут держаться вместе, никакой враг нас не одолеет.', '', '', '', 0),
(14291, 'ruRU', 'Спасение в единстве', 'Теперь ты $g обучился:обучилась; всему, что может сохранить тебе жизнь в эти нелегкие дни.$B$BНам пора присоединиться к остальным беженцам. Кажется, кто-то упомянул, что на юге нас ждет король Седогрив со своей верной стражей.$B$BМы должны идти туда, ибо в единстве наше спасение.', 'Поговорите с королем Генном Седогривом в Военном квартале.', 'Ты правильно поступил, придя сюда. Если все жители Гилнеаса будут держаться вместе, никакой враг нас не одолеет.', '', '', '', 0);

DELETE FROM `quest_template_locale` WHERE `locale` IN ('ptBR', 'itIT', 'zhCN') AND `ID` IN (14265, 14266, 14269, 14272, 14273, 14274, 14275, 14276, 14277, 14278, 14279, 14280, 14281, 14283, 14285, 14286, 14287, 14288, 14289, 14290, 14291);

DELETE FROM `quest_template_locale` WHERE `locale` IN ('deDE', 'esES', 'esMX', 'frFR', 'ruRU', 'ptBR') AND `ID` IN (14007, 14008, 14009, 14010, 14011, 14012, 14013);
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `OfferRewardText`, `RequestItemsText`, `EndText`, `ObjectiveText1`, `VerifiedBuild`) VALUES
(14007, 'deDE', 'Zuverlässiger Schuss', 'Ich bin Bäm Megabombe, Euer persönlicher Lehrer, $g Sir:Madame;.$B$BMir wurde berichtet, dass Ihr Euch für das Leben als $c interessiert?$B$BDann seid Ihr hier an der richtigen Adresse. Ich glaube, Ihr werdet davon profitieren, wenn ich Euch die Kunst des zuverlässigen Schusses beibringe. Unter Umständen ist es genau das, was Ihr braucht, um eine weitere Stufe auf der Karriereleiter zu erklimmen, wenn Ihr wisst, was ich meine.$B$BLernt die Fähigkeit bei mir, und übt sie dann an der Trainingsattrappe hier.', 'Sprecht mit Bäm Megabombe, um ''Zuverlässiger Schuss'' zu lernen und schießt dann dreimal auf eine Trainingsattrappe.', 'Gern geschehen, Boss!$B$BKommt jederzeit zurück, wenn Ihr mehr lernen wollt. Ich bringe Euch alles bei, was ich weiß.', '', '', 'Übt ''Zuverlässiger Schuss''', 0),
(14008, 'deDE', 'Arkane Geschosse', 'Ich bin Zisch Zündel, Euer persönlicher Lehrer, $g Sir:Madame;.$B$BMir wurde berichtet, dass Ihr Euch für das Leben als $c interessiert?$B$BDann seid Ihr hier an der richtigen Adresse. Ich glaube, Ihr werdet davon profitieren, wenn ich Euch die Kunst der arkanen Geschosse beibringe. Unter Umständen ist es genau das, was Ihr braucht, um eine weitere Stufe auf der Karriereleiter zu erklimmen, wenn Ihr wisst, was ich meine.$B$BLernt den Zauber von mir, dann übt ihn ein paarmal an einer Trainingsattrappe am Hof im Südosten.', 'Sprecht mit Zisch Zündel, um ''Arkane Geschosse'' zu lernen und wendet den Zauber dann zweimal auf eine Trainingsattrappe an.$B$BBedenkt dabei, dass für ''Arkane Geschosse'' die Chance besteht, durch die Nutzung anderer offensiver Zauber ausgelöst zu werden. Verwendet zuerst Euren Zauber ''Feuerball'' auf eine Trainingsattrappe, um ''Arkane Geschosse'' zu ermöglichen.', 'Gern geschehen, Boss!$B$BKommt jederzeit zurück, wenn Ihr mehr lernen wollt. Ich bringe Euch alles bei, was ich weiß.', '', '', 'Übt ''Arkane Geschosse''', 0),
(14009, 'deDE', 'Blitzheilung', 'Ich bin Schwester Goldglanz, Eure persönliche Lehrerin, $g Sir:Madame;.$B$BMir wurde berichtet, dass Ihr Euch für das Leben als $c interessiert?$B$BDann seid Ihr hier an der richtigen Adresse. Ich glaube, Ihr werdet davon profitieren, wenn ich Euch die Kunst der Blitzheilung beibringe. Unter Umständen ist es genau das, was Ihr braucht, um eine weitere Stufe auf der Karriereleiter zu erklimmen, wenn Ihr wisst, was ich meine.$B$BLernt den Zauber von mir, dann benutzt ihn, um die verletzten Angestellten im Hof zu heilen.', 'Sprecht mit Schwester Goldschimmer, um ''Blitzheilung'' zu lernen, und wendet den Zauber dann dreimal auf einen verletzten Angestellten an.', 'Gern geschehen, Boss!$B$BKommt jederzeit zurück, wenn Ihr mehr lernen wollt. Ich bringe Euch alles bei, was ich weiß.', '', '', 'Übt ''Blitzheilung''', 0),
(14010, 'deDE', 'Ausweiden', 'Ich bin Slinky Scharfklinge, Euer persönlicher Lehrer, $g Sir:Madame;.$B$BMir wurde berichtet, dass Ihr Euch für das Leben als $c interessiert?$B$BDann seid Ihr hier an der richtigen Adresse. Ich glaube, Ihr werdet davon profitieren, wenn ich Euch die Kunst des Ausweidens beibringe. Unter Umständen ist es genau das, was Ihr braucht, um eine weitere Stufe auf der Karriereleiter zu erklimmen, wenn Ihr wisst, was ich meine.$B$BLernt die Fähigkeit von mir, dann übt sie an einer Trainingsattrape in der südöstlichen Ecke des Hofs.', 'Sprecht mit Slinky Scharfklinge, um ''Ausweiden'' zu lernen, und wendet es dann dreimal auf eine Trainingsattrappe an.$B$BDenkt daran, ''Ausweiden'' erfordert Combopunkte, also schlagt die Trainingsattrappe zunächst mit ''Finsterer Stoß''.', 'Gern geschehen, Boss!$B$BKommt jederzeit zurück, wenn Ihr mehr lernen wollt. Ich bringe Euch alles bei, was ich weiß.', 'Wann immer Ihr dazu bereit seid, mein Herr.', '', 'Übt ''Ausweiden''', 0),
(14011, 'deDE', 'Urtümlicher Schlag', 'Ich bin Lawinus Maximus, Euer persönlicher Lehrer, $g Sir:Madame;.$B$BMir wurde berichtet, dass Ihr Euch für das Leben als $c interessiert?$B$BDann seid Ihr hier an der richtigen Adresse. Ich glaube, Ihr werdet davon profitieren, wenn ich Euch die Kunst des urtümlichen Schlags beibringe. Unter Umständen ist es genau das, was Ihr braucht, um eine weitere Stufe auf der Karriereleiter zu erklimmen, wenn Ihr wisst, was ich meine.$B$BLernt ihn von mir, dann benutzt ihn an einer der Trainingsattrappen im Südosten.', 'Sprecht mit Lawinus Maximus, um ''Urtümlicher Schlag'' zu lernen und wendet ihn dann zweimal auf eine Trainingsattrappe an.', 'Gern geschehen, Boss!$B$BKommt jederzeit zurück, wenn Ihr mehr lernen wollt. Ich bringe Euch alles bei, was ich weiß.', 'Wann immer Ihr dazu bereit seid, mein Herr.', '', 'Übt ''Urtümlicher Schlag''', 0),
(14012, 'deDE', 'Feuerbrand', 'Ich bin Bosa Blick, Euer persönlicher Lehrer, $g Sir:Madame;.$B$BMir wurde berichtet, dass Ihr Euch für das Leben als $c interessiert?$B$BDann seid Ihr hier an der richtigen Adresse. Ich glaube, Ihr werdet davon profitieren, wenn ich Euch die Kunst des Feuerbrands beibringe. Unter Umständen ist es genau das, was Ihr braucht, um eine weitere Stufe auf der Karriereleiter zu erklimmen, wenn Ihr wisst, was ich meine.$B$BLernt den Zauber von mir, dann wirkt ihn auf eine der Trainingsattrappen im Südosten.', 'Sprecht mit Bosa Blick, um ''Feuerbrand'' zu lernen, dann wirkt den Zauber 3-mal auf eine Trainingsattrappe.', 'Gern geschehen, Boss!$B$BKommt jederzeit zurück, wenn Ihr mehr lernen wollt. Ich bringe Euch alles bei, was ich weiß.', '', '', 'Übt ''Feuerbrand''', 0),
(14013, 'deDE', 'Sturmangriff', '<Der Kriegomatic NX-01 schaltet sich ein.>$B$BBoss $N erkannt. Ich bin Kriegomatic NX-01.$B$BMünzen einwerfen, um Sturmangriff auf Feinde zu lernen. Nach Ausbildung bitte auf Trainingsattrappe in der Nähe anwenden.', 'Sprecht mit dem Kriegomatic NX-01, um ''Sturmangriff'' zu lernen. Führt den Angriff dann auf eine Trainingsattrappe aus.', 'Der Kriegomatic NX-01 ist programmiert, um zu dienen.$B$BKehrt jederzeit zurück, wenn Ihr etwas lernen wollt. Diese Einheit bringt Euch alles bei, was sie weiß.', 'Kriegomatic NX-01 online und bereit, mein Herr.', '', 'Übt ''Sturmangriff''', 0),
(14007, 'esES', 'Disparo firme', 'Hola, soy Bamm Megabomba, tu instructor personal, $g señor:señora;.$B$BEntiendo que deseas recibir algunas nuevas perspectivas acerca de lo que supone ser $g un:una; $c, ¿no? No busques más.$B$BCreo que saldrás ganando enormemente si te enseño cómo realizar un Disparo firme. Seguro que te ayuda a trepar por la jerarquía corporativa, ya sabes lo que quiero decir.$B$BAprende la facultad conmigo y luego practica con un muñeco de entrenamiento de aquí.', 'Habla con Bamm Megabomba para aprender Disparo firme, luego dispara a un muñeco de entrenamiento 3 veces.', '', '', '', 'Disparo firme practicado', 0),
(14009, 'esES', 'Sanación relámpago', 'Hola, soy la hermana Sacacuartos, tu instructora personal, $g señor:señora;.$B$BEntiendo que deseas recibir algunas nuevas perspectivas acerca de lo que supone ser $g un:una; $c, ¿no? No busques más.$B$BCreo que saldrás ganando enormemente si te enseño cómo lanzar Sanación relámpago. Seguro que te ayuda a trepar por la jerarquía corporativa, ya sabes lo que quiero decir.$B$BApréndela conmigo y luego úsala para sanar a los empleados heridos que hay alrededor del patio.', 'Habla con la hermana Sacacuartos para aprender Sanación relámpago y luego lanza el hechizo 3 veces sobre un empleado herido.', '', '', '', 'Sanación relámpago practicada', 0),
(14010, 'esES', 'Eviscerar', 'Hola, soy Finta Navajazos, tu instructora personal, $g señor:señora;.$B$BEntiendo que deseas recibir algunas nuevas perspectivas acerca de lo que supone ser $g un:una; $c, ¿no? No busques más.$B$BCreo que saldrás ganando enormemente si te enseño cómo realizar Eviscerar. Seguro que te ayuda a trepar por la jerarquía corporativa, ya sabes lo que quiero decir.$B$BAprende la facultad conmigo y luego ve a practicar con uno de los muñecos de entrenamiento que hay en el extremo sureste del patio.', 'Habla con Finta Navajazos para aprender Eviscerar, luego úsala 3 veces sobre un muñeco de entrenamiento.$B$BRecuerda, Eviscerar requiere puntos de combo, así que primero golpea al muñeco con Golpe siniestro.', '¡Ahí tienes, patrón!$B$BVuelve cuando quieras más entrenamiento. Te enseñaré todo lo que sé.', 'Cuando estés listo, señor.', '', 'Eviscerar practicado', 0),
(14011, 'esES', 'Golpe primigenio', 'Hola, soy Maxx Avalancha, tu instructor personal, $g señor:señora;.$B$BEntiendo que deseas recibir algunas nuevas perspectivas acerca de lo que supone ser $g un:una; $c, ¿no? No busques más.$B$BCreo que saldrás ganando enormemente si te enseño cómo realizar Golpe primigenio. Seguro que te ayuda a trepar por la jerarquía corporativa, ya sabes lo que quiero decir.$B$BApréndelo conmigo y luego ve a practicar con un muñeco de entrenamiento al sureste.', 'Habla con Maxx Avalancha para aprender Golpe primigenio, luego úsalo 2 veces sobre un muñeco de entrenamiento.', '', '', '', 'Golpe primigenio practicado', 0),
(14007, 'esMX', 'Disparo firme', 'Hola, soy Bamm Megabomba, tu instructor personal, $g señor:señora;.$B$BEntiendo que deseas recibir algunas nuevas perspectivas acerca de lo que supone ser $g un:una; $c, ¿no? No busques más.$B$BCreo que saldrás ganando enormemente si te enseño cómo realizar un Disparo firme. Seguro que te ayuda a trepar por la jerarquía corporativa, ya sabes lo que quiero decir.$B$BAprende la facultad conmigo y luego practica con un muñeco de entrenamiento de aquí.', 'Habla con Bamm Megabomba para aprender Disparo firme, luego dispara a un muñeco de entrenamiento 3 veces.', '', '', '', 'Disparo firme practicado', 0),
(14009, 'esMX', 'Sanación relámpago', 'Hola, soy la hermana Sacacuartos, tu instructora personal, $g señor:señora;.$B$BEntiendo que deseas recibir algunas nuevas perspectivas acerca de lo que supone ser $g un:una; $c, ¿no? No busques más.$B$BCreo que saldrás ganando enormemente si te enseño cómo lanzar Sanación relámpago. Seguro que te ayuda a trepar por la jerarquía corporativa, ya sabes lo que quiero decir.$B$BApréndela conmigo y luego úsala para sanar a los empleados heridos que hay alrededor del patio.', 'Habla con la hermana Sacacuartos para aprender Sanación relámpago y luego lanza el hechizo 3 veces sobre un empleado herido.', '', '', '', 'Sanación relámpago practicada', 0),
(14010, 'esMX', 'Eviscerar', 'Hola, soy Finta Navajazos, tu instructora personal, $g señor:señora;.$B$BEntiendo que deseas recibir algunas nuevas perspectivas acerca de lo que supone ser $g un:una; $c, ¿no? No busques más.$B$BCreo que saldrás ganando enormemente si te enseño cómo realizar Eviscerar. Seguro que te ayuda a trepar por la jerarquía corporativa, ya sabes lo que quiero decir.$B$BAprende la facultad conmigo y luego ve a practicar con uno de los muñecos de entrenamiento que hay en el extremo sureste del patio.', 'Habla con Finta Navajazos para aprender Eviscerar, luego úsala 3 veces sobre un muñeco de entrenamiento.$B$BRecuerda, Eviscerar requiere puntos de combo, así que primero golpea al muñeco con Golpe siniestro.', '¡Ahí tienes, patrón!$B$BVuelve cuando quieras más entrenamiento. Te enseñaré todo lo que sé.', 'Cuando estés listo, señor.', '', 'Eviscerar practicado', 0),
(14011, 'esMX', 'Golpe primigenio', 'Hola, soy Maxx Avalancha, tu instructor personal, $g señor:señora;.$B$BEntiendo que deseas recibir algunas nuevas perspectivas acerca de lo que supone ser $g un:una; $c, ¿no? No busques más.$B$BCreo que saldrás ganando enormemente si te enseño cómo realizar Golpe primigenio. Seguro que te ayuda a trepar por la jerarquía corporativa, ya sabes lo que quiero decir.$B$BApréndelo conmigo y luego ve a practicar con un muñeco de entrenamiento al sureste.', 'Habla con Maxx Avalancha para aprender Golpe primigenio, luego úsalo 2 veces sobre un muñeco de entrenamiento.', '', '', '', 'Golpe primigenio practicado', 0),
(14007, 'frFR', 'Le tir assuré', 'Je m''appelle Bamm Mégabombe et je suis votre maître de classe personnel, $g m''sieur:m''dame;.$B$BJe me suis laissé dire que vous aimeriez apprendre quelques nouveautés sur l''art d''être $g un:une; $c. Eh bien, ne cherchez plus.$B$BVous ferez une affaire en me laissant vous enseigner la maîtrise du tir assuré. Et puis ça pourrait vous aider à gravir les échelons, si vous voyez ce que je veux dire.$B$BApprenez cette compétence auprès de moi, puis faites-vous la main sur un de ces mannequins d’entraînement.', 'Parlez à Bamm Mégabombe pour qu’il vous enseigne le Tir assuré, puis faites 3 fois mouche sur un mannequin d’entraînement en utilisant cette technique.', '', '', '', 'S’exercer au Tir assuré', 0),
(14008, 'frFR', 'Les projectiles des Arcanes', 'Je m''appelle Bulle Briquet et je suis votre maître de classe personnel, $g m''sieur:m''dame;.$B$BJe me suis laissé dire que vous aimeriez apprendre quelques nouveautés sur l''art d''être $g un:une; $c. Ne cherchez plus !$B$BVous ferez une affaire en me laissant vous enseigner la maîtrise des projectiles des Arcanes. Et puis ça pourrait vous aider à gravir les échelons, si vous voyez ce que je veux dire.$B$BLaissez-moi vous apprendre ce sort, puis exercez-vous à le lancer plusieurs fois sur un mannequin d''entraînement de l''autre côté de la cour, au sud-est.', 'Allez voir Bulle Briquet qui vous enseignera les Projectiles des Arcanes, puis exercez-vous à lancer ce sort.', '', '', '', 'S’exercer à lancer des Projectiles des Arcanes.', 0),
(14009, 'frFR', 'Les soins rapides', 'Je m''appelle sœur Écumelor et je suis votre maître de classe personnel, $g m''sieur:m''dame;.$B$BJe me suis laissé dire que vous aimeriez apprendre quelques nouveautés sur l''art d''être $g un:une; $c. Ne cherchez plus !$B$BVous ferez une affaire en me laissant vous enseigner la maîtrise des soins rapides. Et puis ça pourrait vous aider à gravir les échelons, si vous voyez ce que je veux dire.$B$BLaissez-moi vous apprendre ce sort, puis exercez-vous à l''utiliser pour soigner les employés blessés qui se trouvent dans la cour.', 'Parlez à Sœur Écumelor qui vous enseignera les Soins rapides. Ensuite, lancez ce sort 3 fois sur un Employé blessé.', 'Et voilà, boss !$B$BRevenez quand vous voulez pour d''autres leçons. Je vous enseignerai mes connaissances.', '', '', 'S''exercer à lancer le sort Soins rapides', 0),
(14010, 'frFR', 'L''éviscération', 'Je m''appelle Fugace Coutelard et je suis votre maître de classe personnel, $g m''sieur:m''dame;.$B$BJe me suis laissé dire que vous aimeriez apprendre quelques nouveautés sur l''art d''être $g un:une; $c. Ne cherchez plus !$B$BVous ferez une affaire en me laissant vous enseigner la maîtrise de l''Éviscération. Et puis ça pourrait vous aider à gravir les échelons, si vous voyez ce que je veux dire.$B$BLaissez-moi vous apprendre cette technique, puis allez vous exercer à l''utiliser sur un mannequin d''entraînement à l''extrémité sud-est de la cour.', 'Parlez à Fugace Coutelard qui vous enseignera l''Éviscération. Ensuite, utilisez cette technique 3 fois sur un Mannequin d''entraînement.$B$BSouvenez-vous, l''Éviscération requiert des points de combo, vous devez donc commencer par frapper le mannequin en utilisant l''Attaque pernicieuse.', '', '', '', 'S’exercer à l’Éviscération', 0),
(14011, 'frFR', 'La frappe primordiale', 'Je m''appelle Maxx Avalanche et je suis votre maître de classe personnel, $g m''sieur:m''dame;.$B$BJe me suis laissé dire que vous aimeriez apprendre quelques nouveautés sur l''art d''être $g un:une; $c. Ne cherchez plus !$B$BVous ferez une affaire en me laissant vous enseigner la maîtrise de la Frappe primordiale. Et puis ça pourrait vous aider à gravir les échelons, si vous voyez ce que je veux dire.$B$BLaissez-moi vous apprendre cette technique, puis allez vous exercer à l''utiliser sur un mannequin d''entraînement, au sud-est.', 'Parlez à Maxx Avalanche qui vous enseignera la Frappe primordiale. Ensuite, utilisez cette technique 2 fois sur un Mannequin d''entraînement.', 'Et voilà, boss !$B$BRevenez quand vous voulez pour d''autres leçons. Je vous enseignerai mes connaissances.', '', '', 'Frappe primordiale pratiquée', 0),
(14012, 'frFR', 'L''immolation', 'Je m''appelle Doigt Bolik et je suis votre maître de classe personnel, $g m''sieur:m''dame;.$B$BJe me suis laissé dire que vous aimeriez apprendre quelques nouveautés sur l''art d''être $g un:une; $c. Ne cherchez plus !$B$BVous ferez une affaire en me laissant vous enseigner la maîtrise de l''Immolation. Et puis ça pourrait vous aider à gravir les échelons, si vous voyez ce que je veux dire.$B$BLaissez-moi vous enseigner ce sort, puis exercez-vous à le lancer sur un mannequin d''entraînement, au sud-est.', 'Allez voir Doigt Bolik qui vous enseignera l''Immolation, puis exercez-vous à lancer ce sort 3 fois sur un Mannequin d''entraînement.', 'Et voilà, boss !$B$BRevenez quand vous voulez pour d''autres leçons. Je vous enseignerai mes connaissances.', '', '', 'S''exercer à lancer le sort Immolation', 0),
(14013, 'frFR', 'À la charge !', '<Le Mécano-guerrier NX-01 s''active.>$B$BIndividu $N détecté. Je suis le Mécano-guerrier NX-01.$B$BInsérez une pièce pour apprendre comment charger vos adversaires. Une fois cette formation reçue, utilisez la Charge sur un des mannequins d’entraînement.', 'Interagissez avec le Mécano-guerrier NX-01 pour qu’il vous enseigne la Charge, puis utilisez cette technique sur un mannequin d’entraînement.', '', '', '', 'S’exercer à la Charge', 0),
(14007, 'ruRU', '"Верный выстрел"', 'Я Бамм Взрыбомм, твой наставник.$B$BКак я понимаю, ты собираешься стать $g великим:великой; |3-4($c)? Ну что же, будем учиться.$B$BНачнем с "Верного выстрела". Это полезное умение. И неплохой шанс заслужить уважение собратьев по цеху.$B$BИзучи данное умение и потренируйся на манекене.', 'Поговорите с Баммом Взрыбоммом, обучитесь приему "Верный выстрел" и поразите тренировочный манекен 3 раза.', 'Ну вот. Очень даже неплохо!$B$BЗахочешь еще поучиться, всегда обращайся. В любое время. Я тебя с радостью научу всему, что знаю.', '', '', 'Использована способность "Верный выстрел"', 0),
(14008, 'ruRU', 'Чародейские стрелы', 'Я Физз Лихтер, твой наставник.$B$BКак я понимаю, ты собираешься стать $g великим:великой; |3-4($c)? Ну что же, будем учиться.$B$BНачнем с "Чародейских стрел". Это полезное умение. И неплохой шанс заслужить уважение собратьев по цеху. Изучи данное заклинание и потренируйся на манекене, что стоит в юго-восточной части двора.', 'Поговорите с Физзом Лихтером и обучитесь заклинанию "Чародейские стрелы", после чего дважды опробуйте его на тренировочном манекене.$B$BПомните, что "Чародейские стрелы" можно использовать только с некоторой вероятностью после применения других атакующих заклинаний. Для того чтобы активировать "Чародейские стрелы", вначале используйте на тренировочном манекене заклинание "Огненный шар".', 'Вот и все, босс!$B$BПриходи, если захочешь еще что-то освоить. Я тебя научу всему, что знаю.', '', '', 'Использовано заклинание "Чародейские стрелы"', 0),
(14009, 'ruRU', 'Быстрое исцеление', 'Я сестра Горазлата, твой наставник.$B$BКак я понимаю, ты собираешься стать $g великим:великой; |3-4($c)? Ну что же, будем учиться.$B$BНачнем с "Быстрого исцеления". Это полезное умение. И неплохой шанс заслужить уважение собратьев по цеху. Изучи данное заклинание и потренируйся в исцелении раненых сотрудников во дворе.', 'Поговорите с сестрой Горазлатой и обучитесь заклинанию "Быстрое исцеление", после чего трижды используйте его на раненом сотруднике.', 'Вот и все, босс!$B$BПриходи, если захочешь еще что-то освоить. Я тебя научу всему, что знаю.', '', '', 'Использовано заклинание "Быстрое исцеление"', 0),
(14010, 'ruRU', 'Потрошение', 'Я Крадли Дротик, твоя наставница.$B$BКак я понимаю, ты собираешься стать $g великим:великой; |3-4($c)? Ну что же, будем учиться.$B$BНачнем с "Потрошения". Это полезное умение. И неплохой шанс заслужить уважение собратьев по цеху. Изучи данное умение и потренируйся на манекене, что стоит в юго-восточном углу двора.', 'Поговорите с Крадли Дротик и обучитесь приему "Потрошение", после чего трижды опробуйте его на тренировочном манекене.$B$BПомните, что данный прием является продолжением серии, поэтому для начала потребуется применить против манекена умение "Коварный удар".', 'Вот и все, босс!$B$BПриходи, если захочешь еще что-то освоить. Я тебя научу всему, что знаю.', '', '', 'Использована способность "Потрошение"', 0),
(14011, 'ruRU', '"Стихийный удар"', 'Я Максс Оползень, твой наставник.$B$BКак я понимаю, ты собираешься стать $g великим:великой; |3-4($c)? Ну что же, будем учиться.$B$BНачнем со "Стихийного удара". Это полезное умение. И неплохой шанс заслужить уважение собратьев по цеху. Изучи данное умение и потренируйся на манекене, что стоит в юго-восточном углу двора.', 'Поговорите с Макссом Оползнем и обучитесь приему "Стихийный удар", после чего дважды опробуйте его на тренировочном манекене.', 'Вот и все, босс!$B$BПриходи, если захочешь еще что-то освоить. Я тебя научу всему, что знаю.', '', '', 'Попрактикуйте "Стихийный удар"', 0),
(14012, 'ruRU', 'Жертвенный огонь', 'Я Ехид Опальчик, твой наставник.$B$BКак я понимаю, ты собираешься стать $g великим:великой; |3-4($c)? Ну что же, будем учиться.$B$BНачнем с "Жертвенного огня". Это полезное умение. И неплохой шанс заслужить уважение собратьев по цеху. Изучи данное заклинание и потренируйся на манекене, что стоит в юго-восточной части двора.', 'Поговорите с Ехидом Опальчиком и обучитесь заклинанию "Жертвенный огонь", после чего трижды опробуйте его на тренировочном манекене.', 'Вот и все, босс!$B$BПриходи, если захочешь еще что-то освоить. Я тебя научу всему, что знаю.', '', '', 'Использовано заклинание "Жертвенный огонь"', 0),
(14013, 'ruRU', 'Рывок', '<Воин-матик NX-01 включается в оперативный режим.>$B$BОбнаружен босс $N. Я Воин-матик NX-01.$B$BОпустите монету, чтобы получить сеанс массажа или обучиться приему "Рывок". После изучения приема потренируйтесь на манекене, что стоит поблизости.', 'Поговорите с Воином-матиком NX-01 и обучитесь приему "Рывок", после чего опробуйте его на тренировочном манекене.', '', '', '', 'Использована способность "Рывок"', 0);

